const payload = $json.body ?? $json;
const headers = $json.headers ?? {};
const configuredToken = 'api-key-test';
const providedToken = String(headers['x-ingest-token'] || headers['X-Ingest-Token'] || '').trim();

if (configuredToken && providedToken !== configuredToken) {
  throw new Error('Token invalido o ausente en header x-ingest-token');
}

const callbackUrl = String(headers['x-callback-url'] || headers['X-Callback-Url'] || '').trim();
const callbackToken = String(headers['x-callback-token'] || headers['X-Callback-Token'] || '').trim();

if (!callbackUrl) {
  throw new Error('No se recibio x-callback-url');
}

if (!callbackToken) {
  throw new Error('No se recibio x-callback-token');
}

const proveedores = [];
if (Array.isArray(payload)) {
  for (const [i, entry] of payload.entries()) {
    const proveedor = entry?.proveedor ?? entry?.supplier ?? `proveedor_${i + 1}`;
    const metadata = entry?.metadata && typeof entry.metadata === 'object' ? entry.metadata : {};
    const productos = Array.isArray(entry?.productos) ? entry.productos : (Array.isArray(entry?.products) ? entry.products : []);
    proveedores.push({ proveedor, metadata, productos });
  }
} else if (payload && typeof payload === 'object') {
  for (const [proveedor, productos] of Object.entries(payload)) {
    proveedores.push({
      proveedor,
      metadata: {},
      productos: Array.isArray(productos) ? productos : [productos],
    });
  }
}

if (!proveedores.length) throw new Error('No se detectaron proveedores/productos en el payload');

const maxSuppliers = 3;
const maxProductsPerSupplier = 30000;
if (proveedores.length > maxSuppliers) {
  throw new Error(`Cantidad de proveedores excede limite (${maxSuppliers})`);
}
for (const item of proveedores) {
  if ((item.productos || []).length > maxProductsPerSupplier) {
    throw new Error(`Proveedor ${item.proveedor} excede limite de productos (${maxProductsPerSupplier})`);
  }
}

const traceId = headers['x-request-id'] || headers['X-Request-Id'] || `trace_${Date.now()}`;
return [{ json: { receivedAt: new Date().toISOString(), traceId, callbackUrl, callbackToken, proveedores } }];

const proveedores = Array.isArray($json.proveedores) ? $json.proveedores : [];

if (!proveedores.length) {
  throw new Error('No hay proveedores para procesar');
}

return proveedores.map((entry, index) => ({
  json: {
    traceId: $json.traceId,
    receivedAt: $json.receivedAt,
    callbackUrl: $json.callbackUrl,
    callbackToken: $json.callbackToken,
    supplierName: String(entry?.proveedor ?? `proveedor_${index + 1}`),
    metadata: entry?.metadata && typeof entry.metadata === 'object' ? entry.metadata : {},
    productos: Array.isArray(entry?.productos) ? entry.productos : [],
  },
}));

const products = Array.isArray($json.productos) ? $json.productos : [];

const normalizeHeader = (value) =>
  String(value || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();

const allHeaders = new Set();
for (const row of products) {
  if (!row || typeof row !== 'object') continue;
  for (const key of Object.keys(row)) {
    allHeaders.add(String(key));
  }
}

const headers = Array.from(allHeaders);

const sampleSize = 20;
const sampleRows = products.slice(0, sampleSize);

const columnStats = headers.map((header) => {
  let nonNullCount = 0;
  let numericLikeCount = 0;
  const examples = [];
  const unique = new Set();

  for (const row of products) {
    if (!row || typeof row !== 'object') continue;
    const value = row[header];
    if (value === null || value === undefined || String(value).trim() === '') {
      continue;
    }

    nonNullCount += 1;

    if (typeof value === 'number') {
      numericLikeCount += 1;
    } else {
      const text = String(value).trim();
      if (/^-?[0-9]+([.,][0-9]+)?$/.test(text)) {
        numericLikeCount += 1;
      }
    }

    if (examples.length < 3) {
      const text = String(value);
      examples.push(text.length > 120 ? `${text.slice(0, 117)}...` : text);
    }

    if (unique.size < 1000) {
      unique.add(String(value));
    }
  }

  return {
    header,
    headerNormalized: normalizeHeader(header),
    nonNullCount,
    nullCount: Math.max(products.length - nonNullCount, 0),
    numericLikeRatio: products.length ? Number((numericLikeCount / products.length).toFixed(3)) : 0,
    uniqueCountApprox: unique.size,
    examples,
  };
});

return {
  json: {
    ...$json,
    profile: {
      totalRows: products.length,
      headers,
      columnStats,
      sampleRows,
    },
  },
};

const providerData = $('Perfilar proveedor').item.json;

const emptyMapping = {
  sku: null,
  supplierSku: null,
  name: null,
  brand: null,
  category: null,
  listPrice: null,
  offerPrice: null,
  taxRate: null,
  barcode: null,
};

if (!providerData) {
  return {
    json: {
      pipelineOk: false,
      stage: 'llm_mapping_link',
      error: 'No se encontro item del proveedor para esta salida del LLM',
      traceId: null,
      supplierName: null,
      productos: [],
      mapping: emptyMapping,
      defaults: { currency: null },
      mappingWarnings: ['Fallo de enlace entre perfil y salida LLM'],
      llmRaw: null,
    },
  };
}

if ($json.error) {
  return {
    json: {
      pipelineOk: false,
      stage: 'llm_mapping_request',
      error: $json.error,
      traceId: providerData.traceId,
      supplierName: providerData.supplierName,
      productos: providerData.productos,
      mapping: emptyMapping,
      defaults: { currency: null },
      mappingWarnings: ['Fallo la llamada al LLM mapeador'],
      llmRaw: null,
    },
  };
}

const rawResponse = $json?.mergedResponse
  ?? ($json?.content?.parts || [])
    .filter((part) => typeof part?.text === 'string')
    .map((part) => part.text)
    .join('\n')
  ?? '';

if (!rawResponse) {
  return {
    json: {
      pipelineOk: false,
      stage: 'llm_mapping_parse',
      error: 'Gemini no devolvio texto en mergedResponse/content.parts',
      traceId: providerData.traceId,
      supplierName: providerData.supplierName,
      productos: providerData.productos,
      mapping: emptyMapping,
      defaults: { currency: null },
      mappingWarnings: ['Respuesta vacia del LLM mapeador'],
      llmRaw: null,
    },
  };
}

const cleaned = rawResponse
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```$/i, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  return {
    json: {
      pipelineOk: false,
      stage: 'llm_mapping_parse',
      error: `El LLM no devolvio JSON valido: ${cleaned.slice(0, 400)}`,
      traceId: providerData.traceId,
      supplierName: providerData.supplierName,
      productos: providerData.productos,
      mapping: emptyMapping,
      defaults: { currency: null },
      mappingWarnings: ['JSON invalido del LLM mapeador'],
      llmRaw: cleaned,
    },
  };
}

const allowedHeaders = Array.isArray(providerData?.profile?.headers)
  ? providerData.profile.headers
  : [];

const normalizeKey = (value) =>
  String(value || '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();

const headerByNorm = new Map();
for (const header of allowedHeaders) {
  const key = normalizeKey(header);
  if (key && !headerByNorm.has(key)) {
    headerByNorm.set(key, header);
  }
}

const resolveHeader = (candidate) => {
  if (candidate === null || candidate === undefined) return null;
  const text = String(candidate).trim();
  if (!text) return null;
  if (allowedHeaders.includes(text)) return text;
  return headerByNorm.get(normalizeKey(text)) || null;
};

const mappingInput = parsed?.mapping && typeof parsed.mapping === 'object'
  ? parsed.mapping
  : {};

const mapping = {
  sku: resolveHeader(mappingInput.sku),
  supplierSku: resolveHeader(mappingInput.supplierSku),
  name: resolveHeader(mappingInput.name),
  brand: resolveHeader(mappingInput.brand),
  category: resolveHeader(mappingInput.category),
  listPrice: resolveHeader(mappingInput.listPrice),
  offerPrice: resolveHeader(mappingInput.offerPrice),
  taxRate: resolveHeader(mappingInput.taxRate),
  barcode: resolveHeader(mappingInput.barcode),
};

const defaultsInput = parsed?.defaults && typeof parsed.defaults === 'object'
  ? parsed.defaults
  : {};

const defaults = {
  currency: defaultsInput.currency == null ? null : String(defaultsInput.currency),
};

const mappingWarnings = Array.isArray(parsed?.warnings)
  ? parsed.warnings.map((w) => String(w))
  : [];

const hasAnyMapping = Object.values(mapping).some((v) => v !== null);

return {
  json: {
    pipelineOk: hasAnyMapping,
    stage: hasAnyMapping ? 'mapping_ok' : 'mapping_empty',
    error: hasAnyMapping ? null : 'El LLM no pudo inferir mapeos utiles',
    traceId: providerData.traceId,
    supplierName: providerData.supplierName,
    productos: providerData.productos,
    mapping,
    defaults,
    mappingConfidence: typeof parsed?.confidence === 'number' ? parsed.confidence : null,
    mappingWarnings,
    llmRaw: cleaned,
  },
};

const mapping = $json.mapping || {};
const products = Array.isArray($json.productos) ? $json.productos : [];

const normalizeKey = (value) =>
  String(value || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();

const toStringOrNull = (value) => {
  if (value === undefined || value === null) return null;
  const text = String(value).trim();
  return text ? text : null;
};

const toNumberOrNull = (value) => {
  if (value === undefined || value === null || value === '') return null;
  if (typeof value === 'number' && Number.isFinite(value)) return value;

  let text = String(value).trim();
  if (!text) return null;

  text = text
    .replace(/\s/g, '')
    .replace(/[$€]/g, '')
    .replace(/%/g, '');

  if (text.includes(',') && text.includes('.')) {
    if (text.lastIndexOf(',') > text.lastIndexOf('.')) {
      text = text.replace(/\./g, '').replace(',', '.');
    } else {
      text = text.replace(/,/g, '');
    }
  } else if (text.includes(',')) {
    text = text.replace(',', '.');
  }

  text = text.replace(/[^0-9.-]/g, '');
  const n = Number(text);
  return Number.isFinite(n) ? n : null;
};

const fallbackSynonyms = {
  sku: ['codigo', 'codigo producto', 'id', 'item', 'referencia', 'ref', 'sku'],
  supplierSku: ['codigo proveedor', 'cod proveedor', 'sku proveedor'],
  name: ['descripcion', 'descripcion del producto', 'detalle', 'articulo', 'nombre'],
  brand: ['marca', 'brand', 'fabricante'],
  category: ['rubro', 'rubro padre', 'categoria', 'familia', 'linea'],
  listPrice: ['precio de lista', 'precio', 'p venta', 'p.venta', 'lista 1', 'lista'],
  offerPrice: ['precio oferta', 'precio promo', 'precio promocion'],
  taxRate: ['iva', '% iva', 'impuesto'],
  barcode: ['codigo barra', 'cod barra', 'ean', 'barcode'],
};

const buildNormalizedKeyMap = (row) => {
  const map = new Map();
  for (const key of Object.keys(row || {})) {
    map.set(normalizeKey(key), key);
  }
  return map;
};

const pickValue = (row, normalizedKeyMap, targetField) => {
  const mappedHeader = mapping[targetField];

  if (mappedHeader && Object.prototype.hasOwnProperty.call(row, mappedHeader)) {
    return row[mappedHeader];
  }

  if (mappedHeader) {
    const resolved = normalizedKeyMap.get(normalizeKey(mappedHeader));
    if (resolved && Object.prototype.hasOwnProperty.call(row, resolved)) {
      return row[resolved];
    }
  }

  const aliases = fallbackSynonyms[targetField] || [];
  for (const alias of aliases) {
    const resolved = normalizedKeyMap.get(normalizeKey(alias));
    if (resolved && Object.prototype.hasOwnProperty.call(row, resolved)) {
      return row[resolved];
    }
  }

  return null;
};

const normalizedProducts = [];

for (const row of products) {
  if (!row || typeof row !== 'object') continue;

  const keyMap = buildNormalizedKeyMap(row);

  const sku = toStringOrNull(pickValue(row, keyMap, 'sku'));
  const supplierSku = toStringOrNull(pickValue(row, keyMap, 'supplierSku'));
  const name = toStringOrNull(pickValue(row, keyMap, 'name'));
  const brand = toStringOrNull(pickValue(row, keyMap, 'brand'));
  const category = toStringOrNull(pickValue(row, keyMap, 'category'));
  const listPrice = toNumberOrNull(pickValue(row, keyMap, 'listPrice'));
  const offerPrice = toNumberOrNull(pickValue(row, keyMap, 'offerPrice'));
  const taxRate = toNumberOrNull(pickValue(row, keyMap, 'taxRate'));
  const barcode = toStringOrNull(pickValue(row, keyMap, 'barcode'));

  const warnings = [];
  if (!name) warnings.push('Falta nombre/descripcion');
  if (!sku && !supplierSku) warnings.push('Falta identificador sku/codigo');
  if (listPrice === null && offerPrice === null) warnings.push('Sin precio detectable');

  const essentialOk = [name, sku || supplierSku, listPrice ?? offerPrice]
    .filter((v) => v !== null && v !== undefined)
    .length;

  const confidenceBase = typeof $json.mappingConfidence === 'number' ? $json.mappingConfidence : 0.75;
  const confidence = Number(Math.max(0, Math.min(1, confidenceBase - warnings.length * 0.1 + (essentialOk === 3 ? 0.05 : 0))).toFixed(3));

  normalizedProducts.push({
    supplierName: $json.supplierName || null,
    sku,
    supplierSku,
    name,
    brand,
    category,
    listPrice,
    offerPrice,
    taxRate,
    barcode,
    originalProduct: row,
    confidence,
    warnings,
  });
}

return {
  json: {
    pipelineOk: normalizedProducts.length > 0,
    stage: normalizedProducts.length > 0 ? 'normalized' : 'normalized_empty',
    error: normalizedProducts.length > 0 ? null : 'No se normalizaron productos para el proveedor',
    traceId: $json.traceId,
    supplierName: $json.supplierName,
    mapping: $json.mapping,
    mappingWarnings: $json.mappingWarnings || [],
    providerWarnings: $json.mappingWarnings || [],
    normalizedProducts,
  },
};

const items = $input.all();
const first = items[0]?.json || {};

const providerResults = items.map((item) => ({
  supplierName: item.json.supplierName || null,
  pipelineOk: !!item.json.pipelineOk,
  stage: item.json.stage || 'unknown',
  error: item.json.error || null,
  normalizedCount: Array.isArray(item.json.normalizedProducts)
    ? item.json.normalizedProducts.length
    : 0,
  warnings: Array.isArray(item.json.providerWarnings)
    ? item.json.providerWarnings
    : [],
}));

const normalizedProducts = items.flatMap((item) =>
  Array.isArray(item.json.normalizedProducts) ? item.json.normalizedProducts : [],
);

const supplierContexts = Object.fromEntries(
  items
    .filter((item) => item.json.supplierName)
    .map((item) => [
      item.json.supplierName,
      {
        sourceFileName: item.json.metadata?.sourceFileName || null,
        uploadedByUserId: item.json.metadata?.uploadedByUserId || null,
      },
    ]),
);

const failedProviders = providerResults.filter((r) => !r.pipelineOk).length;

return [{
  json: {
    ok: failedProviders === 0,
    stage: 'completed',
    traceId: first.traceId || null,
    callbackUrl: first.callbackUrl || null,
    callbackToken: first.callbackToken || null,
    error: failedProviders
      ? `Fallaron ${failedProviders} proveedor(es) durante el procesamiento.`
      : null,
    totalProviders: providerResults.length,
    totalNormalizedProducts: normalizedProducts.length,
    normalizedProducts,
    providerResults,
    supplierContexts,
  },
}];

const payload = $json;
const callbackUrl = String($json.callbackUrl || '').trim();
const callbackToken = String($json.callbackToken || '').trim();

if (!callbackUrl) {
  throw new Error('No se encontro callbackUrl para notificar el resultado');
}

const callbackPayload = {
  ok: payload.ok,
  stage: payload.stage,
  traceId: payload.traceId || null,
  error: payload.error || null,
  totalProviders: payload.totalProviders || 0,
  totalNormalizedProducts: payload.totalNormalizedProducts || 0,
  normalizedProducts: Array.isArray(payload.normalizedProducts) ? payload.normalizedProducts : [],
  providerResults: Array.isArray(payload.providerResults) ? payload.providerResults : [],
  supplierContexts: payload.supplierContexts && typeof payload.supplierContexts === 'object' ? payload.supplierContexts : {},
};

const response = await fetch(callbackUrl, {
  method: 'POST',
  headers: {
    'content-type': 'application/json',
    'x-callback-token': callbackToken,
  },
  body: JSON.stringify(callbackPayload),
});

const responseText = await response.text();

return [{
  json: {
    callbackUrl,
    callbackStatus: response.status,
    callbackOk: response.ok,
    callbackResponse: responseText || null,
    traceId: payload.traceId || null,
  },
}];
